import React, { useEffect, useState, useRef } from "react";

import { getStore,  gen16CodeId, ObjectKeys, AccountYears, setIntervalX} from "../../../stores/Utils";

import {SearchInput_Cmpt } from "../../../components";

import { OpenModal } from "../../../components/DialogHRM";

import "./dashboard.css"
import { InvoiceItem_Cmpt, AddInvoice_Cmpt, ViewPrintCheck_Cmpt } from "..";
import {  getall_invoice, loadInvoicesfromFile, search_invoice } from "../services/server_fetching";
import { get_balances_by_type } from "../../CuentasContables/services/server_fetching";
import ViewInvoiceCompare from "./ViewInvoiceCompare";
import { scan_location_production } from "../../Inventory/services/server_fetching";


const SearchInput = SearchInput_Cmpt();


const InvoiceItem = InvoiceItem_Cmpt();

const MakeSale = AddInvoice_Cmpt();

const ViewPrintCheck = ViewPrintCheck_Cmpt();





const InvoiceDashboard  = ({ data, elmId, updObs }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);
	const [range, set_range] = useState(64);

	const [loading, set_loading] = useState(false);

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			set_obs(gen16CodeId())
			getall_invoice(loadList);
			scan_location_production(updObs);
			get_balances_by_type("global_accounts","global_account_params",updObs);
		}
	});


	const openUpdateView =  () => {
		
	}

	const handleChange =  (v) => {
		!loading && set_loading(true)
	}

	const handle_search_invoice =  (v) => {
		set_loading(true)
		search_invoice(loadList)
	}


	const handle_getall_invoice =  (v) => {
		getall_invoice(loadList)
	}

	const cb_result1 = async (f, v) => {
		set_obs(gen16CodeId())
		
	};




	const openSaleView =  () => {
		let dataModal = {};
		dataModal["zIndex"] = 450;
		dataModal["height"] = "80vh";
		// data['observeResize']=true;
		dataModal["props"] = { minHeight: "1vh", overlay: true };
		dataModal["content"] = 
			<MakeSale />
		
		OpenModal(dataModal);
	}


	const openCompareView =  () => {
		let dataModal = {};
		dataModal["zIndex"] = 450;
		dataModal["height"] = "80vh";
		// data['observeResize']=true;
		dataModal["props"] = { minHeight: "1vh", overlay: true };
		dataModal["content"] = 
			<ViewInvoiceCompare />
		
		OpenModal(dataModal);
	}

	
	const openCheckView =  () => {
		let dataModal = {};
		dataModal["zIndex"] = 450;
		dataModal["height"] = "80vh";
		// data['observeResize']=true;
		dataModal["props"] = { minHeight: "1vh", overlay: true };
		dataModal["content"] = 
			<ViewPrintCheck />
		
		OpenModal(dataModal);
	}

	const cb_result = async (f, v) => {
		if(range!==64){
			set_range(64);
		}
		else{
			set_obs(gen16CodeId())
		}
		set_loading(false);
	};
	
	const loadMore=  () => {
		set_range(v=>v+64)
	}

	const loadList =  () => {

		
		cb_result();

		let factor = Math.ceil(ObjectKeys(getStore("invoices_list"))?.length / 64);

		setIntervalX(loadMore, 1250, factor)

		setTimeout(() => {
			set_loading(false)
		}, 230);
		
	};


	const importCSV =  (event) => {
		var fileReader = new FileReader();
		fileReader.onload = function(fileLoadedEvent){
			var textFromFileLoaded = fileLoadedEvent.target.result;
			loadInvoicesfromFile(textFromFileLoaded)
		
		};
	  
		fileReader.readAsText(event.target.files[0], "UTF-8");
	}

	

	return (

	<div className="">
		<div className="accounts_header">
			<h2>Invoices</h2>
			<div className="_dsplFlx ">
				{AccountYears()[getStore("date_current_year")]?.isClosed?null:
				<p className="group_title addBtn purple" onClick={openSaleView} >
					Add Invoice
				</p>
				}
				<p className="group_title addBtn purple" onClick={openCompareView} >
					Compare Invoice
				</p>
				<p className="group_title addBtn purple" onClick={openCheckView} >
					Print Check
				</p>

				<div className="group_title addBtn purple upl">
					Import Invoices from File
					<input id="fileupload" type = "file" onChange={importCSV}/>
				</div>
				
				
			</div>
			<div className="_dsplFlx " style={{marginTop:14}} >
				<SearchInput
					placeholder={"Buscar ...."} 
					width={360}
					obs={set_obs}
					fetchData={handle_search_invoice}
					loading={loading}
					change={handleChange}
					callempty={handle_getall_invoice}
					keyFlds={"searchQry"}
				/>
				<div className="flexSpace"/>
				<div className="_dsplFlx ">
					<div className="total_comprobante_title">
						No de Invoices: 
					</div>
					<div className="total_comprobante gray">
						<span>
							{ObjectKeys(getStore("invoices_list"))?.length}
						</span>
					</div>
					
				</div>
			</div>
		</div>
		

		<div className="invoices_container scollVh" style={{height: "calc(98vh - 230px)"}}>
			{getStore("invoices_list") && ObjectKeys(getStore("invoices_list"))?.map((cid, index)=>{
				return (
					<InvoiceItem 
						data={getStore("invoices_list")[cid]} 
						elmId={cid} 
						key={cid}
						openUpdateView={openUpdateView}
						handleRefreshAll={handle_getall_invoice}
						show={index < range}
						index={index}
					/>
				)
			})}
		</div>
		</div>
	);
};

export default InvoiceDashboard;



